//! AppBar — reactive component migrated to the canonical pattern.
//!
//! Framework-owned via `ctx.mountOwned(AppBar, .{ .title = ..., .on_close = ... })`:
//! no `init`/`register`/`deinit`/action-id strings. Self-contained title bar:
//! draggable title area plus minimize / maximize / close buttons. Per-button
//! hover is a Signal driving the button background through a fine-grained
//! render-only effect; window actions fire typed handlers wired by (node, kind)
//! through the router (hit modifiers keep the autogenerated "n{id}" action-id, so
//! the C-ABI hit-testing/event channel is unchanged).

const std = @import("std");
const component = @import("component.zig");
const signals = @import("../core/signals.zig");
const events = @import("events.zig");
const props = @import("../core/properties.zig");
const reg = @import("../core/registry.zig");
const icons = @import("icons.zig");
const theme_mod = @import("theme.zig");

const BuildContext = component.BuildContext;

pub const AppBar = struct {
    // Props (set from mountOwned's init_props; re-applied on rebuild).
    title: []const u8 = "",
    /// Accessible names of the caption buttons; override to localize.
    control_labels: component.WindowControlLabels = .{},
    on_close: ?*const fn (ctx: ?*anyopaque) void = null,
    on_maximize: ?*const fn (ctx: ?*anyopaque) void = null,
    on_minimize: ?*const fn (ctx: ?*anyopaque) void = null,
    /// Optional query for the live maximized state, used to flip the maximize
    /// button glyph (chrome_maximize ↔ chrome_restore). Wired by runApp through
    /// the C-ABI; the direct-window path uses `window.isMaximized()` instead.
    is_maximized: ?*const fn (ctx: ?*anyopaque) bool = null,
    on_drag: ?*const fn (ctx: ?*anyopaque) void = null,
    context: ?*anyopaque = null,
    /// Optional direct window handle; when set, the buttons drive it in addition
    /// to firing the callbacks (runApp instead routes through the C-ABI).
    window: ?*const @import("window.zig").Window = null,

    // State (auto-created in onMount; preserved across rebuilds).
    hover_min: signals.Signal(bool) = undefined,
    hover_max: signals.Signal(bool) = undefined,
    hover_close: signals.Signal(bool) = undefined,
    scope: signals.Scope = undefined,

    // Captured during build().
    store: ?*props.PropertyStore = null,
    drag_area: reg.NodeId = reg.NULL_NODE,
    min_btn: reg.NodeId = reg.NULL_NODE,
    max_btn: reg.NodeId = reg.NULL_NODE,
    close_btn: reg.NodeId = reg.NULL_NODE,
    close_hover_bg: props.PropValue = .{ .color = .{ .r = 232.0 / 255.0, .g = 17.0 / 255.0, .b = 35.0 / 255.0, .a = 1.0 } },
    bound: bool = false,
    theme: theme_mod.Theme = .{},

    pub fn onMount(self: *AppBar, allocator: std.mem.Allocator) void {
        self.hover_min = signals.Signal(bool).init(allocator, false);
        self.hover_max = signals.Signal(bool).init(allocator, false);
        self.hover_close = signals.Signal(bool).init(allocator, false);
        self.scope = signals.Scope.init(allocator);
    }

    /// Tears down reactive state on unmount. The framework owns and frees
    /// the instance itself.
    pub fn deinit(self: *AppBar) void {
        self.scope.deinit();
        self.hover_min.deinit();
        self.hover_max.deinit();
        self.hover_close.deinit();
    }

    /// Live maximized state, preferring the direct window handle, then the C-ABI
    /// query callback. Read fresh in build(); the maximize handler triggers a
    /// rebuild so the glyph refreshes (resize alone doesn't re-run build).
    fn queryMaximized(self: *AppBar) bool {
        if (self.window) |w| return @constCast(w).isMaximized();
        if (self.is_maximized) |f| return f(self.context);
        return false;
    }

    fn onDragDown(self: *AppBar, _: events.Event) void {
        if (self.window) |w| @constCast(w).startDrag();
        if (self.on_drag) |cb| cb(self.context);
    }
    fn onMinClick(self: *AppBar, _: events.Event) void {
        if (self.window) |w| @constCast(w).minimize();
        if (self.on_minimize) |cb| cb(self.context);
    }
    fn onMaxClick(self: *AppBar, _: events.Event) void {
        if (self.window) |w| @constCast(w).maximize();
        // The callback (runApp path) toggles the window AND triggers a UI rebuild,
        // so build() re-reads the OS state and swaps the maximize/restore glyph.
        if (self.on_maximize) |cb| cb(self.context);
    }
    fn onCloseClick(self: *AppBar, _: events.Event) void {
        if (self.window) |w| @constCast(w).close();
        if (self.on_close) |cb| cb(self.context);
    }

    pub fn build(self: *AppBar, ctx: *BuildContext) !void {
        const b = ctx.builder;
        self.store = b.store;
        self.theme = b.theme;

        const root = try b.openNodeKeyed(.box, null);
        try b.width(root, 100, .percent);
        try b.height(root, 32, .px);
        try b.flexRow(root);
        try b.alignItems(root, .center);
        try b.justifyContent(root, .space_between);
        try b.background(root, b.theme.accent.r, b.theme.accent.g, b.theme.accent.b);
        try b.borderWidth(root, b.theme.border_width);
        try b.borderColor(root, b.theme.accent_hover.r, b.theme.accent_hover.g, b.theme.accent_hover.b);
        try b.role(root, "app_bar");

        // Close-hover background follows the theme's danger role when set;
        // falls back to the Windows chrome red on unthemed setups (a=0 token).
        if (b.theme.danger.a > 0) {
            const d = b.theme.danger;
            self.close_hover_bg = .{ .color = .{
                .r = @as(f32, @floatFromInt(d.r)) / 255.0,
                .g = @as(f32, @floatFromInt(d.g)) / 255.0,
                .b = @as(f32, @floatFromInt(d.b)) / 255.0,
                .a = 1.0,
            } };
        }

        // Draggable title area.
        self.drag_area = try b.openNodeKeyed(.box, null);
        try b.backgroundAlpha(self.drag_area, 0, 0, 0, 0.0);
        try b.flexRow(self.drag_area);
        try b.width(self.drag_area, 0, .px);
        try b.flexGrow(self.drag_area, 1);
        try b.height(self.drag_area, 100, .percent);
        try b.alignItems(self.drag_area, .center);
        try b.padding(self.drag_area, 0, 0, 0, 16);
        try wireHit(b, self.drag_area, true, false);
        if (ctx.router) |r| try r.onNode(self.drag_area, .mouse_down, ctx.handler(self, onDragDown));
        const txt = try b.addText(self.title);
        try b.fontSize(txt, 14);
        try b.textColor(txt, b.theme.text_on_accent.r, b.theme.text_on_accent.g, b.theme.text_on_accent.b);
        b.close(); // drag_area

        // Window controls.
        const controls = try b.openNodeKeyed(.box, null);
        try b.backgroundAlpha(controls, 0, 0, 0, 0.0);
        try b.flexRow(controls);
        try b.width(controls, 144, .px);
        try b.height(controls, 100, .percent);

        // Codicons chrome-* glyphs (framework/icons.zig) for the minimize / maximize /
        // close controls, rendered via the bundled icon-font fallback.
        // The maximize button shows restore (double square) when maximized; the
        // live OS state is read here and refreshed by the maximize handler's rebuild.
        const max_glyph = if (self.queryMaximized()) icons.chrome_restore else icons.chrome_maximize;
        const max_label = if (self.queryMaximized()) self.control_labels.restore else self.control_labels.maximize;
        self.min_btn = try controlButton(ctx, icons.chrome_minimize, self.control_labels.minimize, 16, ctx.handler(self, onMinClick), &self.hover_min);
        self.max_btn = try controlButton(ctx, max_glyph, max_label, 16, ctx.handler(self, onMaxClick), &self.hover_max);
        self.close_btn = try controlButton(ctx, icons.chrome_close, self.control_labels.close, 16, ctx.handler(self, onCloseClick), &self.hover_close);

        b.close(); // controls
        b.close(); // root

        // Hover highlights are a fine-grained render-only effect (created once,
        // re-applied untracked after a structural rebuild) — same as Button.
        try component.bindVisuals(self, &self.scope, &self.bound, updateVisuals);
    }

    fn controlButton(
        ctx: *BuildContext,
        glyph: []const u8,
        label: []const u8,
        font: f32,
        on_click: events.Handler,
        hover: *signals.Signal(bool),
    ) !reg.NodeId {
        const b = ctx.builder;
        const btn = try b.openNodeKeyed(.box, null);
        try b.width(btn, 48, .px);
        try b.height(btn, 100, .percent);
        try b.alignItems(btn, .center);
        try b.justifyContent(btn, .center);
        try wireHit(b, btn, true, true);
        // Icon-only control: the glyph child isn't a readable name, so expose an
        // explicit accessible name for UIA / screen readers.
        try b.ariaLabel(btn, label);
        if (ctx.router) |r| {
            try r.onNode(btn, .click, on_click);
            const hh = ctx.signalSetter(hover);
            try r.onNode(btn, .mouse_enter, hh);
            try r.onNode(btn, .mouse_leave, hh);
        }
        const t = try b.addText(glyph);
        try b.fontSize(t, font);
        try b.textColor(t, b.theme.text_on_accent.r, b.theme.text_on_accent.g, b.theme.text_on_accent.b);
        b.close();
        return btn;
    }

    /// Sets hit modifiers with the autogenerated "n{id}" action-id (C-ABI channel).
    fn wireHit(b: *component.UIBuilder, id: reg.NodeId, click: bool, hover: bool) !void {
        var idbuf: [16]u8 = undefined;
        const auto_id = std.fmt.bufPrint(&idbuf, "n{d}", .{id}) catch "n";
        if (click) try b.clickable(id, auto_id);
        if (hover) try b.hoverable(id, auto_id);
    }

    fn updateVisuals(self: *AppBar) void {
        const store = self.store orelse return;
        if (self.min_btn == reg.NULL_NODE) return;
        const Theme = theme_mod.Theme;
        const t = self.theme;
        // Min/Max: M3 state layer hover (on_accent over accent at 8%) instead of
        // the old fixed white(0.2) overlay that failed on light themes.
        const hl = Theme.stateLayer(t.accent, t.text_on_accent, .hover);
        const hl_bg = props.PropValue.rgbA(hl.r, hl.g, hl.b, @as(f32, @floatFromInt(hl.a)) / 255.0);
        const transparent_bg = props.PropValue{ .color = .{ .r = 0, .g = 0, .b = 0, .a = 0 } };
        store.setStyle(self.min_btn, .background, if (self.hover_min.get()) hl_bg else transparent_bg) catch {};
        store.setStyle(self.max_btn, .background, if (self.hover_max.get()) hl_bg else transparent_bg) catch {};
        // Close button: danger role on hover (destructive action, not a state layer).
        const close_bg: props.PropValue = if (self.hover_close.get())
            self.close_hover_bg
        else
            transparent_bg;
        store.setStyle(self.close_btn, .background, close_bg) catch {};
    }
};

// white() removed — replaced by Theme.stateLayer (M3 state layers).

// ── Tests ─────────────────────────────────────────────────────────────────────

const testing = std.testing;

fn mountBar(
    registry: *reg.UIRegistry,
    store: *props.PropertyStore,
    router: *events.EventRouter,
    mounts: *component.MountTable,
    init_props: anytype,
) !*AppBar {
    var b = component.UIBuilder.init(registry, store);
    var ctx = BuildContext{ .builder = &b, .router = router, .mounts = mounts };
    _ = try b.openNodeKeyed(.box, null); // root
    try ctx.mountOwned(AppBar, init_props);
    b.close();
    const anchor = registry.getNode(0).?.first_child;
    return @ptrCast(@alignCast(mounts.get(anchor).?.component_ptr));
}

test "AppBar (mountOwned) close hover turns the close button red; click fires on_close" {
    const a = testing.allocator;
    var registry = reg.UIRegistry.init(a);
    defer registry.deinit();
    var store = props.PropertyStore.init(a);
    defer store.deinit();
    store.setRegistry(&registry);
    var router = events.EventRouter.init(a);
    defer router.deinit();
    var mounts = component.MountTable.init(a);
    defer mounts.deinit();
    registry.addNodeRemovedListener(&mounts, component.MountTable.nodeRemovedListener);

    const Holder = struct {
        var closed: u32 = 0;
        fn onClose(_: ?*anyopaque) void {
            closed += 1;
        }
    };
    Holder.closed = 0;

    const bar = try mountBar(&registry, &store, &router, &mounts, .{
        .title = "Title",
        .on_close = Holder.onClose,
    });

    // Idle close button: transparent.
    try testing.expectApproxEqAbs(@as(f32, 0.0), store.getStyle(bar.close_btn, .background).?.color.a, 0.001);

    for (registry.nodes.items) |*n| {
        n.layout_dirty = false;
        n.render_dirty = false;
    }

    _ = router.route(.{ .name = "mouse_enter", .id = "", .node_id = bar.close_btn });
    const bg = store.getStyle(bar.close_btn, .background).?.color;
    try testing.expectApproxEqAbs(@as(f32, 232.0 / 255.0), bg.r, 0.001);
    try testing.expectApproxEqAbs(@as(f32, 1.0), bg.a, 0.001);
    // Hover is render-only.
    var any_layout = false;
    for (registry.nodes.items) |*n| {
        if (n.alive and n.layout_dirty) any_layout = true;
    }
    try testing.expect(!any_layout);

    _ = router.route(.{ .name = "click", .id = "", .node_id = bar.close_btn });
    try testing.expectEqual(@as(u32, 1), Holder.closed);
}

test "AppBar drag fires on_drag on mouse_down" {
    const a = testing.allocator;
    var registry = reg.UIRegistry.init(a);
    defer registry.deinit();
    var store = props.PropertyStore.init(a);
    defer store.deinit();
    store.setRegistry(&registry);
    var router = events.EventRouter.init(a);
    defer router.deinit();
    var mounts = component.MountTable.init(a);
    defer mounts.deinit();
    registry.addNodeRemovedListener(&mounts, component.MountTable.nodeRemovedListener);

    const Holder = struct {
        var dragged: u32 = 0;
        fn onDrag(_: ?*anyopaque) void {
            dragged += 1;
        }
    };
    Holder.dragged = 0;

    const bar = try mountBar(&registry, &store, &router, &mounts, .{
        .title = "Title",
        .on_drag = Holder.onDrag,
    });

    _ = router.route(.{ .name = "mouse_down", .id = "", .node_id = bar.drag_area });
    try testing.expectEqual(@as(u32, 1), Holder.dragged);
}
